private.reference_solution:
using System.Reflection;

var name = (Console.ReadLine() ?? "").Trim();
var type = typeof(TaskInfoAttribute).Assembly.GetTypes()
    .FirstOrDefault(candidate => candidate.Name == name);
if (type is null) Environment.Exit(1);
var info = type.GetCustomAttribute<TaskInfoAttribute>();
if (info is null) Environment.Exit(1);
Console.WriteLine($"owner={info.Owner} priority={info.Priority}");

[AttributeUsage(AttributeTargets.Class)]
sealed class TaskInfoAttribute : Attribute
{
    public string Owner { get; init; } = "";
    public int Priority { get; init; }
}

[TaskInfo(Owner = "ops", Priority = 2)]
sealed class Audit { }

[TaskInfo(Owner = "dev", Priority = 5)]
sealed class Export { }
